<?php /** @var array $rows @var int $year @var int $tol */ ?>
<div class="page-head"><div><h1><?= icon('scale') ?> <?= e(t('recon.title')) ?> — <?= (int)$year ?></h1><p class="sub"><?= e(t('recon.subtitle')) ?></p></div>
  <form method="get" action="<?= e(url('incidents/reconciliation')) ?>" class="filters"><div class="field"><label for="year"><?= e(t('sha.year')) ?></label><input type="number" id="year" name="year" min="2000" max="2100" value="<?= (int)$year ?>"></div><div class="field"><button class="btn secondary" type="submit"><?= e(t('common.apply')) ?></button></div></form>
  <div class="actions noprint"><a class="btn secondary" href="<?= e(url('incidents')) ?>"><?= e(t('common.back')) ?></a><?php if (can('recon.manage')): ?><a class="btn gold" href="<?= e(url('import')) ?>"><?= e(t('recon.load')) ?></a><?php endif; ?><button class="btn" type="button" data-print><?= e(t('common.print')) ?></button></div></div>
<p class="muted"><?= e(t('recon.tolerance', ['t' => money(\App\Core\Money::toDb($tol))])) ?></p>
<div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('recon.period')) ?></th><th class="num"><?= e(t('recon.incident_net')) ?></th><th class="num"><?= e(t('recon.gl_total')) ?></th><th class="num"><?= e(t('recon.difference')) ?></th><th><?= e(t('recon.state')) ?></th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): $from = $r['period'] . '-01'; $to = date('Y-m-t', strtotime($from)); ?><tr><td class="nowrap"><?= e($r['period']) ?></td>
<td class="num"><a href="<?= e(url('incidents', ['from' => $from, 'to' => $to, 'type' => 'incident'])) ?>"><?= e(money(\App\Core\Money::toDb($r['incidents']))) ?></a> <span class="muted">(<?= (int)$r['inc_n'] ?>)</span></td>
<td class="num"><?= $r['gl'] === null ? '—' : e(money(\App\Core\Money::toDb($r['gl']))) ?></td><td class="num"><?= $r['diff'] === null ? '—' : e(money(\App\Core\Money::toDb($r['diff']))) ?></td>
<td><span class="badge <?= $r['state'] === 'ok' ? 'ok' : ($r['state'] === 'diff' ? 'danger' : 'warn') ?>"><?= e(t('recon.s_' . $r['state'])) ?></span></td>
<td><?php if ($r['gl'] !== null && can('recon.manage')): ?><form method="post" class="inline" action="<?= e(url('incidents/reconciliation/delete')) ?>" data-confirm="<?= e(t('recon.confirm_delete', ['p' => $r['period']])) ?>"><?= csrf_field() ?><input type="hidden" name="period" value="<?= e($r['period']) ?>"><button class="btn small danger" type="submit"><?= e(t('recon.delete')) ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
